//! Golden-vector conformance: fixtures generated by the C++ upstream
//! implementation (`tools/golden_vectors/generate.cpp`, libtorrent v2.1.2).
//! Decode must succeed, structure must match, and canonical re-encode must
//! be byte-identical.
use bitdaemon_bencode::{Entry, NodeType, bdecode, bencode};

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("tests/data/{name}.bin")).expect("fixture")
}

#[test]
fn golden_sorted_dict() {
    let buf = fixture("bencode_sorted_dict");
    let root = bdecode(&buf);
    assert!(root.error().is_none());
    assert_eq!(root.node_type(), NodeType::Dict);

    assert_eq!(root.dict_find_int_value(b"a", -1), 42);
    assert_eq!(root.dict_find_string_value(b"b", b""), b"x");
    let c = root.dict_find_list(b"c");
    assert_eq!(c.node_type(), NodeType::List);
    assert_eq!(c.list_size(), 1);
    assert_eq!(c.list_string_value_at(0, b"?"), b"");

    // canonical re-encode is byte-identical to upstream output
    assert_eq!(bencode(&Entry::from(&root)), buf);
}

#[test]
fn golden_edge_ints() {
    let buf = fixture("bencode_edge_ints");
    let root = bdecode(&buf);
    assert!(root.error().is_none());
    assert_eq!(root.dict_find_string_value(b"empty", b"x"), b"");

    // upstream quirk: i64::MIN overflows `parse_int` in
    // `bdecode_node::int_value()` — upstream returns 0, so do we.
    assert_eq!(root.dict_find_int_value(b"n", -1), 0);

    // re-encoding the decoded 0 is NOT byte-identical here — upstream
    // itself cannot round-trip this value; assert the raw field span is
    // preserved verbatim in the wire bytes instead.
    let n = root.dict_find(b"n");
    assert_eq!(n.node_type(), NodeType::Int);
}
